// FindGame retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindGame(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*Game, error) {
	if len(cols) == 0 {
		return Games.Query(
			ctx, exec,
			SelectWhere.Games.ID.EQ(IDPK),
		).One()
	}

	return Games.Query(
		ctx, exec,
		SelectWhere.Games.ID.EQ(IDPK),
		sm.Columns(Games.Columns().Only(cols...)),
	).One()
}

// GameExists checks the presence of a single record by primary key
func GameExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return Games.Query(
		ctx, exec,
		SelectWhere.Games.ID.EQ(IDPK),
	).Exists()
}

// PrimaryKeyVals returns the primary key values of the Game
func (o *Game) PrimaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

// Update uses an executor to update the Game
func (o *Game) Update(ctx context.Context, exec bob.Executor, s *GameSetter) error {
	return Games.Update(ctx, exec, s, o)
}

// Delete deletes a single Game record with an executor
func (o *Game) Delete(ctx context.Context, exec bob.Executor) error {
	return Games.Delete(ctx, exec, o)
}

// Reload refreshes the Game using the executor
func (o *Game) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := Games.Query(
		ctx, exec,
		SelectWhere.Games.ID.EQ(o.ID),
	).One()
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

func (o GameSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals GameSetter) error {
	return Games.Update(ctx, exec, &vals, o...)
}

func (o GameSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	return Games.Delete(ctx, exec, o...)
}

func (o GameSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	var mods []bob.Mod[*dialect.SelectQuery]

	IDPK := make([]string, len(o))

	for i, o := range o {
		IDPK[i] = o.ID
	}

	mods = append(mods,
		SelectWhere.Games.ID.In(IDPK...),
	)

	o2, err := Games.Query(ctx, exec, mods...).All()
	if err != nil {
		return err
	}

	for _, old := range o {
		for _, new := range o2 {
			if new.ID != old.ID {
				continue
			}
			new.R = old.R
			*old = *new
			break
		}
	}

	return nil
}

