func (o *Game) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServers":
		rels, ok := retrieved.(GameServerSlice)
		if !ok {
			return fmt.Errorf("game cannot load %T as %q", retrieved, name)
		}

		o.R.GameServers = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Game = o
			}
		}
		return nil
	case "Logs":
		rels, ok := retrieved.(LogSlice)
		if !ok {
			return fmt.Errorf("game cannot load %T as %q", retrieved, name)
		}

		o.R.Logs = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Game = o
			}
		}
		return nil
	default:
		return fmt.Errorf("game has no relationship %q", name)
	}
}

func ThenLoadGameGameServers(queryMods ...bob.Mod[*dialect.SelectQuery]) sqlite.Loader {
	return sqlite.Loader(func(ctx context.Context, exec bob.Executor, retrieved any) error {
		loader, isLoader := retrieved.(interface {
			LoadGameGameServers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
		})
		if !isLoader {
			return fmt.Errorf("object %T cannot load GameGameServers", retrieved)
		}

		err := loader.LoadGameGameServers(ctx, exec, queryMods...)

		// Don't cause an issue due to missing relationships
		if errors.Is(err, sql.ErrNoRows) {
			return nil
		}

		return err
	})
}

// LoadGameGameServers loads the game's GameServers into the .R struct
func (o *Game) LoadGameGameServers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.GameServers = nil

	related, err := o.GameServers(ctx, exec, mods...).All()
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Game = o
	}

	o.R.GameServers = related
	return nil
}

// LoadGameGameServers loads the game's GameServers into the .R struct
func (os GameSlice) LoadGameGameServers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServers(ctx, exec, mods...).All()
	if err != nil {
		return err
	}

	for _, o := range os {
		o.R.GameServers = nil
	}

	for _, o := range os {
		for _, rel := range gameServers {
			if o.ID != rel.GameID {
				continue
			}

			rel.R.Game = o

			o.R.GameServers = append(o.R.GameServers, rel)
		}
	}

	return nil
}

